WITH scored AS (SELECT id, page, event_time, MAX(duration_sec) OVER (PARTITION BY event_type) event_type_max_duration_sec, COUNT(duration_sec) OVER (PARTITION BY page ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) duration_sec_count_30d FROM web_events WHERE duration_sec != 196) SELECT id, event_time, event_type_max_duration_sec, duration_sec_count_30d FROM scored;
